guides/agents/agent-safety.mdx.command:
relate query --database ./team.rl --mode envelope <<'EOF'
.begin
MATCH (p:Project {name: 'opencypher-tck'}) DETACH DELETE p;
MATCH (p:Project) RETURN count(p) AS projects;
.rollback
MATCH (p:Project) RETURN count(p) AS projects;
EOF

guides/cli/scripting.mdx.command:
status=0
relate --database ./team.rl --read-only --mode envelope --timeout 5s "MATCH (p:Person) RETRUN p.name" > result.jsonl 2> error.txt || status=$?
case "$status" in
  0) echo "ok" ;;
  5) echo "conflict" ;;
  6) echo "rejected: $(head -n 1 error.txt)" ;;
  7) echo "timed out" ;;
  *) echo "failed with exit code $status" ;;
esac

reference/cli/index.mdx.command:
printf '.begin
CREATE (:Note);
.rollback
MATCH (n:Note) RETURN count(n) AS notes;
' | relate query --mode envelope

reference/storage/wal-and-checkpoints.md.command:
cat > team.cypher <<'EOF'
CREATE (:Person {name: 'Ada', role: 'engineer'});
CREATE (:Person {name: 'Grace', role: 'engineer'});
CREATE (:Person {name: 'Noor', role: 'maintainer'});
EOF
relate query --database ./team < team.cypher
relate info --database ./team
ls -A team/wal
cat team/wal/00000002.log; echo
